import { setCapabilityOverrides, setKeybindings } from "@earendil-works/pi-tui";
import { afterAll, beforeAll, describe, expect, test } from "vitest";
import { Container } from "../../tui/src/tui.ts";
import { KeybindingsManager } from "../src/core/keybindings.ts";
import { InteractiveMode } from "../src/modes/interactive/interactive-mode.ts";
import { initTheme } from "../src/modes/interactive/theme/theme.ts";

// Regression guard for hummin's startup header and What's New section: the rendered output must not change when the code that builds them moves between files.
// The header goes through the real InteractiveMode.init() path.

const HEADER_BUILT = new Error("header built");

/** InteractiveMode methods are private, so tests reach them by name through the prototype. */
const proto = InteractiveMode.prototype as unknown as Record<string, (this: unknown) => unknown>;

/** A stand-in that accepts any property read or call, so init() can run up to the header without the real session. */
function looseStub(overrides: Record<string, unknown> = {}): unknown {
	const stub: unknown = new Proxy(() => stub, {
		get: (_target, key) =>
			key in overrides ? overrides[key as string] : key === "then" || key === Symbol.toPrimitive ? undefined : stub,
		apply: () => stub,
	});
	return stub;
}

async function renderHeader(
	options: { verbose: boolean; quietStartup: boolean },
	widths: number[],
): Promise<Record<number, string[]>> {
	const headerContainer = new Container();
	const own: Record<string, unknown> = {
		isInitialized: false,
		version: "1.2.3",
		options: { verbose: options.verbose },
		toolOutputExpanded: false,
		headerContainer,
		documentContainer: new Container(),
		pendingMessagesContainer: new Container(),
		statusContainer: new Container(),
		widgetContainerAbove: new Container(),
		editorContainer: new Container(),
		widgetContainerBelow: new Container(),
		footerContainer: new Container(),
		session: { scopedModels: [] },
		settingsManager: looseStub({ getQuietStartup: () => options.quietStartup }),
		// init() requests a render right after the header is mounted: stop there.
		ui: looseStub({
			requestRender: () => {
				throw HEADER_BUILT;
			},
		}),
	};
	const self: unknown = new Proxy(own, {
		get: (target, key) => {
			if (key in target) return target[key as string];
			// Real prototype methods that init() calls on the way to the header; everything else is a stub.
			if (
				key === "getStartupExpansionState" ||
				key === "shouldShowStartupDetails" ||
				key === "shouldShowStartupHeader"
			) {
				return proto[key].bind(self);
			}
			return looseStub();
		},
		set: (target, key, value) => {
			target[key as string] = value;
			return true;
		},
	});
	await expect(proto.init.call(self)).rejects.toBe(HEADER_BUILT);
	const result: Record<number, string[]> = {};
	for (const width of widths) result[width] = headerContainer.children.flatMap((child) => child.render(width));
	return result;
}

function renderWhatsNew(collapseChangelog: boolean, expand: boolean, width: number): string[] {
	const chatContainer = new Container();
	const self: Record<string, unknown> = {
		startupNoticesShown: false,
		version: "1.2.3",
		changelogMarkdown: "## [1.2.3]\n\n### Added\n\n- A thing that was added\n- Another thing",
		chatContainer,
		settingsManager: { getCollapseChangelog: () => collapseChangelog, getCodeBlockIndent: () => "  " },
		ui: { requestRender: () => {} },
	};
	self.getMarkdownThemeWithSettings = () => proto.getMarkdownThemeWithSettings.call(self);
	proto.showStartupNoticesIfNeeded.call(self);
	if (expand) {
		const section = chatContainer.children.find((child) => child.handleMouse);
		// A real left click on the section header row toggles it.
		section?.handleMouse?.({ type: "click", button: "left", y: 0 } as Parameters<
			NonNullable<typeof section.handleMouse>
		>[0]);
	}
	return chatContainer.children.flatMap((child) => child.render(width));
}

